"""Utilidades NGSI-LD para Orion y QuantumLeap."""

from __future__ import annotations

import json
import time
from datetime import datetime, timezone
from typing import Dict, Iterable, List, Optional

import requests


DEFAULT_TIMEOUT = 20


def now_iso() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def ngsi_property(value):
    return {"type": "Property", "value": value}


def ngsi_relationship(object_id: str):
    return {"type": "Relationship", "object": object_id}


def ngsi_geoproperty(geo_value: Dict):
    return {"type": "GeoProperty", "value": geo_value}


def request_json(
    method: str,
    url: str,
    headers: Optional[Dict] = None,
    params: Optional[Dict] = None,
    payload: Optional[Dict] = None,
    timeout: int = DEFAULT_TIMEOUT,
):
    response = requests.request(
        method=method,
        url=url,
        headers=headers,
        params=params,
        data=json.dumps(payload) if payload is not None else None,
        timeout=timeout,
    )
    if response.status_code >= 400:
        raise RuntimeError(f"HTTP {response.status_code} {url}: {response.text[:600]}")
    if not response.text.strip():
        return None
    if "application/json" in response.headers.get("Content-Type", ""):
        return response.json()
    return response.text


def retry(operation, retries: int = 3, sleep_seconds: float = 1.5):
    last_error = None
    for _ in range(retries):
        try:
            return operation()
        except Exception as exc:  # noqa: BLE001
            last_error = exc
            time.sleep(sleep_seconds)
    raise last_error


def bulk_upsert_orion(orion_url: str, headers: Dict, entities: Iterable[Dict]):
    payload = {
        "actionType": "upsert",
        "entities": list(entities),
    }
    endpoint = f"{orion_url.rstrip('/')}/entityOperations/upsert"
    return retry(lambda: request_json("POST", endpoint, headers=headers, payload=payload))


def delete_entity_if_exists(orion_url: str, headers: Dict, entity_id: str):
    endpoint = f"{orion_url.rstrip('/')}/entities/{entity_id}"
    response = requests.delete(endpoint, headers=headers, timeout=DEFAULT_TIMEOUT)
    if response.status_code in (200, 204, 404):
        return
    raise RuntimeError(f"Delete failed for {entity_id}: {response.status_code} {response.text[:500]}")


def patch_entity_attrs(orion_url: str, headers: Dict, entity_id: str, attrs: Dict):
    endpoint = f"{orion_url.rstrip('/')}/entities/{entity_id}/attrs"
    return retry(lambda: request_json("PATCH", endpoint, headers=headers, payload=attrs))


def list_entities(
    orion_url: str,
    headers: Dict,
    entity_type: Optional[str] = None,
    q: Optional[str] = None,
    limit: int = 1000,
):
    endpoint = f"{orion_url.rstrip('/')}/entities"
    params = {"limit": limit}
    if entity_type:
        params["type"] = entity_type
    if q:
        params["q"] = q
    return retry(lambda: request_json("GET", endpoint, headers=headers, params=params)) or []


def get_entity(orion_url: str, headers: Dict, entity_id: str):
    endpoint = f"{orion_url.rstrip('/')}/entities/{entity_id}"
    return retry(lambda: request_json("GET", endpoint, headers=headers))


def plain_value(attr):
    if isinstance(attr, dict) and "value" in attr:
        return attr["value"]
    if isinstance(attr, dict) and "object" in attr:
        return attr["object"]
    return attr


def normalize_entity(entity: Dict) -> Dict:
    out = {"id": entity.get("id"), "type": entity.get("type")}
    for key, value in entity.items():
        if key in ("id", "type", "@context"):
            continue
        out[key] = plain_value(value)
    return out


def post_iot_agent(iot_agent_url: str, payload: Dict):
    endpoint = f"{iot_agent_url.rstrip('/')}/iot/devices"
    headers = {"Content-Type": "application/json", "Fiware-Service": "openiot", "Fiware-ServicePath": "/"}
    return request_json("POST", endpoint, headers=headers, payload=payload)


def create_iot_service_group(iot_agent_url: str, payload: Dict):
    endpoint = f"{iot_agent_url.rstrip('/')}/iot/services"
    headers = {"Content-Type": "application/json", "Fiware-Service": "openiot", "Fiware-ServicePath": "/"}
    response = requests.post(endpoint, headers=headers, data=json.dumps(payload), timeout=DEFAULT_TIMEOUT)
    if response.status_code in (201, 204, 409):
        return
    raise RuntimeError(f"IoT service group failed: {response.status_code} {response.text[:400]}")


def create_orion_subscription(orion_url: str, headers: Dict, subscription_payload: Dict):
    endpoint = f"{orion_url.rstrip('/')}/subscriptions"
    response = requests.post(endpoint, headers=headers, data=json.dumps(subscription_payload), timeout=DEFAULT_TIMEOUT)
    if response.status_code in (201, 409):
        return response.headers.get("Location")
    if response.status_code == 422 and "Already Exists" in response.text:
        return None
    raise RuntimeError(f"Subscription failed: {response.status_code} {response.text[:600]}")


def query_quantumleap_series(ql_url: str, entity_id: str, attrs: List[str], last_n: int = 200):
    series = {}
    for attr in attrs:
        endpoint = f"{ql_url.rstrip('/')}/v2/entities/{entity_id}/attrs/{attr}"
        try:
            data = request_json("GET", endpoint, params={"lastN": last_n})
            values = data.get("values", []) if isinstance(data, dict) else []
            series[attr] = values
        except Exception:  # noqa: BLE001
            series[attr] = []
    return series

#!/usr/bin/env python3
"""Crea suscripciones Orion para QuantumLeap y backend /notify."""

from __future__ import annotations

import argparse
import json
from typing import Dict, List

import requests

from catalog import NGSI_LD_CONTEXT, ORION_ENTITY_HEADERS


def build_headers() -> Dict[str, str]:
    return {
        "Accept": "application/ld+json",
        "Content-Type": "application/ld+json",
        "Link": f'<{NGSI_LD_CONTEXT}>; rel="http://www.w3.org/ns/json-ld#context"; type="application/ld+json"',
    }


def list_subscriptions(orion_url: str, headers: Dict[str, str]) -> List[Dict]:
    endpoint = f"{orion_url.rstrip('/')}/subscriptions"
    response = requests.get(endpoint, headers=headers, timeout=20)
    if response.status_code != 200:
        raise RuntimeError(f"No se pudieron listar suscripciones: {response.status_code} {response.text[:500]}")
    return response.json()


def create_subscription(orion_url: str, headers: Dict[str, str], payload: Dict):
    endpoint = f"{orion_url.rstrip('/')}/subscriptions"
    response = requests.post(endpoint, headers=headers, data=json.dumps(payload), timeout=20)
    if response.status_code in (201, 204):
        return
    if response.status_code == 409:
        return
    raise RuntimeError(f"Error creando suscripcion: {response.status_code} {response.text[:700]}")


def ensure_subscription(orion_url: str, headers: Dict[str, str], payload: Dict):
    existing = list_subscriptions(orion_url, headers)
    names = {sub.get("name", {}).get("value") for sub in existing if isinstance(sub.get("name"), dict)}
    if payload["name"]["value"] in names:
        print(f"[subscriptions] Ya existe: {payload['name']['value']}")
        return
    create_subscription(orion_url, headers, payload)
    print(f"[subscriptions] Creada: {payload['name']['value']}")


def ql_subscription(ql_url: str) -> Dict:
    return {
        "id": "urn:ngsi-ld:Subscription:auravault-ql-history",
        "type": "Subscription",
        "name": {"type": "Property", "value": "auravault-ql-history"},
        "description": {
            "type": "Property",
            "value": "Persistencia historica en QuantumLeap para observaciones y estado de dispositivos",
        },
        "entities": [
            {"type": "IndoorEnvironmentObserved"},
            {"type": "NoiseLevelObserved"},
            {"type": "CrowdFlowObserved"},
            {"type": "Device"},
        ],
        "notification": {
            "attributes": [
                "dateObserved",
                "temperature",
                "relativeHumidity",
                "co2",
                "illuminance",
                "LAeq",
                "LAmax",
                "LAS",
                "peopleCount",
                "occupancy",
                "deviceState",
                "batteryLevel",
                "latencyMs",
            ],
            "format": "normalized",
            "endpoint": {
                "uri": ql_url.rstrip("/") + "/v2/notify",
                "accept": "application/json",
            },
        },
        "isActive": {"type": "Property", "value": True},
        "@context": [NGSI_LD_CONTEXT],
    }


def backend_subscription(backend_notify_url: str) -> Dict:
    return {
        "id": "urn:ngsi-ld:Subscription:auravault-backend-notify",
        "type": "Subscription",
        "name": {"type": "Property", "value": "auravault-backend-notify"},
        "description": {
            "type": "Property",
            "value": "Envio de eventos de Orion al backend Flask para WebSocket y reglas de negocio",
        },
        "entities": [
            {"type": "IndoorEnvironmentObserved"},
            {"type": "NoiseLevelObserved"},
            {"type": "CrowdFlowObserved"},
            {"type": "Alert"},
            {"type": "Actuator"},
            {"type": "Device"},
            {"type": "Artwork"},
        ],
        "notification": {
            "format": "normalized",
            "endpoint": {
                "uri": backend_notify_url,
                "accept": "application/json",
            },
        },
        "isActive": {"type": "Property", "value": True},
        "@context": [NGSI_LD_CONTEXT],
    }


def main():
    parser = argparse.ArgumentParser(description="Crear suscripciones Orion")
    parser.add_argument("--orion-url", default="http://localhost:1026/ngsi-ld/v1")
    parser.add_argument("--ql-url", default="http://quantumleap:8668")
    parser.add_argument("--backend-notify-url", default="http://backend:5000/notify")
    args = parser.parse_args()

    headers = build_headers()

    ensure_subscription(args.orion_url, headers, ql_subscription(args.ql_url))
    ensure_subscription(args.orion_url, headers, backend_subscription(args.backend_notify_url))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Backend Flask + SocketIO para AuraVault."""

from __future__ import annotations

import io
import json
import math
import os
import random
import sys
import time
from collections import defaultdict
from datetime import datetime, timedelta, timezone
from pathlib import Path
from threading import Lock
from typing import Dict, List, Optional, Tuple

import numpy as np
import requests
from flask import (
    Flask,
    Response,
    jsonify,
    make_response,
    render_template,
    request,
    send_file,
)
from flask_socketio import SocketIO
from reportlab.lib.pagesizes import A4
from reportlab.pdfgen import canvas
from sklearn.ensemble import RandomForestRegressor
from sklearn.linear_model import LogisticRegression

ROOT = Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path:
    sys.path.append(str(ROOT))

from scripts.catalog import (  # noqa: E402
    MUSEUMS,
    NGSI_LD_CONTEXT,
    ORION_ENTITY_HEADERS,
    ROOM_NEIGHBORS,
    ROOMS,
    room_location,
)
from scripts.ngsi_utils import (  # noqa: E402
    bulk_upsert_orion,
    ngsi_property,
    normalize_entity,
    patch_entity_attrs,
)


ORION_URL = os.environ.get("ORION_URL", "http://localhost:1026/ngsi-ld/v1")
QL_URL = os.environ.get("QL_URL", "http://localhost:8668")
GRAFANA_URL = os.environ.get("GRAFANA_URL", "http://localhost:3000")
OLLAMA_URL = os.environ.get("OLLAMA_URL", "http://localhost:11434/api/generate")
OLLAMA_MODEL = os.environ.get("OLLAMA_MODEL", "gemma3:latest")
OPENAI_API_KEY = os.environ.get("OPENAI_API_KEY")
OPENAI_MODEL = os.environ.get("OPENAI_MODEL", "gpt-4o-mini")


app = Flask(
    __name__,
    static_folder=str(ROOT / "backend" / "static"),
    template_folder=str(ROOT / "backend" / "templates"),
)
app.config["SECRET_KEY"] = os.environ.get("FLASK_SECRET", "auravault-dev-secret")

socketio = SocketIO(app, cors_allowed_origins="*", async_mode="eventlet")


rate_limit_memory: Dict[str, List[float]] = defaultdict(list)
rate_limit_lock = Lock()

risk_model: Optional[RandomForestRegressor] = None
failure_model: Optional[LogisticRegression] = None


def utc_now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def parse_iso(value: str) -> datetime:
    return datetime.fromisoformat(value.replace("Z", "+00:00"))


def orion_headers() -> Dict[str, str]:
    return ORION_ENTITY_HEADERS.copy()


def request_json(
    method: str,
    url: str,
    headers: Optional[Dict] = None,
    params: Optional[Dict] = None,
    payload: Optional[Dict] = None,
    timeout: float = 15.0,
):
    response = requests.request(
        method=method,
        url=url,
        headers=headers,
        params=params,
        data=json.dumps(payload) if payload is not None else None,
        timeout=timeout,
    )
    if response.status_code >= 400:
        raise RuntimeError(f"HTTP {response.status_code} {url}: {response.text[:400]}")
    if not response.text.strip():
        return None
    if "application/json" in response.headers.get("Content-Type", ""):
        return response.json()
    return response.text


def orion_get(path: str, params: Optional[Dict] = None):
    return request_json("GET", f"{ORION_URL.rstrip('/')}/{path.lstrip('/')}", headers=orion_headers(), params=params)


def orion_post(path: str, payload: Dict):
    return request_json("POST", f"{ORION_URL.rstrip('/')}/{path.lstrip('/')}", headers=orion_headers(), payload=payload)


def orion_patch(path: str, payload: Dict):
    return request_json("PATCH", f"{ORION_URL.rstrip('/')}/{path.lstrip('/')}", headers=orion_headers(), payload=payload)


def orion_list(entity_type: Optional[str] = None, q: Optional[str] = None, limit: int = 1000) -> List[Dict]:
    params = {"limit": limit}
    if entity_type:
        params["type"] = entity_type
    if q:
        params["q"] = q
    data = orion_get("entities", params=params)
    return data if isinstance(data, list) else []


def orion_get_entity(entity_id: str) -> Optional[Dict]:
    try:
        data = orion_get(f"entities/{entity_id}")
        return data if isinstance(data, dict) else None
    except Exception:  # noqa: BLE001
        return None


def normalize_entities(entities: List[Dict]) -> List[Dict]:
    return [normalize_entity(entity) for entity in entities]


def resolve_center(center_id: str) -> Dict:
    for museum in MUSEUMS:
        if center_id in {museum["id"], museum["code"]}:
            return museum
        if museum["id"].endswith(center_id):
            return museum
    raise KeyError(center_id)


def resolve_room(room_id: str) -> Dict:
    for room in ROOMS:
        if room_id in {room["id"], room["id"].split(":")[-1]}:
            return room
    raise KeyError(room_id)


def center_rooms(center_id: str) -> List[Dict]:
    return [room for room in ROOMS if room["museumId"] == center_id]


def room_latest_entities() -> Tuple[Dict[str, Dict], Dict[str, Dict], Dict[str, Dict]]:
    env_entities = normalize_entities(orion_list("IndoorEnvironmentObserved", limit=1000))
    noise_entities = normalize_entities(orion_list("NoiseLevelObserved", limit=1000))
    crowd_entities = normalize_entities(orion_list("CrowdFlowObserved", limit=1000))

    env_by_room: Dict[str, Dict] = {}
    noise_by_room: Dict[str, Dict] = {}
    crowd_by_room: Dict[str, Dict] = {}

    for env in env_entities:
        room_id = env.get("refPointOfInterest")
        if room_id:
            env_by_room[room_id] = env

    for noise in noise_entities:
        room_id = noise.get("refPointOfInterest")
        if room_id:
            noise_by_room[room_id] = noise

    for crowd in crowd_entities:
        room_id = crowd.get("refRoadSegment") or crowd.get("refPointOfInterest")
        if room_id:
            crowd_by_room[room_id] = crowd

    return env_by_room, noise_by_room, crowd_by_room


def room_status(room: Dict, env: Optional[Dict], noise: Optional[Dict], crowd: Optional[Dict]) -> str:
    if not env:
        return "attention"

    co2 = float(env.get("co2", 700))
    hum = float(env.get("relativeHumidity", 50))
    temp = float(env.get("temperature", 21))
    laeq = float((noise or {}).get("LAeq", 50))
    occupancy = float((crowd or {}).get("occupancy", 0.0))

    critical = (
        co2 > 1300
        or hum < 35
        or hum > 65
        or temp < 16
        or temp > 28
        or laeq > 82
        or occupancy > 0.95
    )
    if critical:
        return "critical"

    attention = (
        co2 > 1000
        or hum < 40
        or hum > 60
        or temp < 18
        or temp > 25
        or laeq > 70
        or occupancy > 0.8
    )
    return "attention" if attention else "optimal"


def center_snapshot(center_id: str) -> Dict:
    rooms = center_rooms(center_id)
    env_by_room, noise_by_room, crowd_by_room = room_latest_entities()

    values = {
        "temperature": [],
        "humidity": [],
        "co2": [],
        "noise": [],
        "occupancy": [],
        "people": [],
    }
    statuses = []

    for room in rooms:
        env = env_by_room.get(room["id"], {})
        noise = noise_by_room.get(room["id"], {})
        crowd = crowd_by_room.get(room["id"], {})

        statuses.append(room_status(room, env, noise, crowd))

        if env:
            values["temperature"].append(float(env.get("temperature", 0.0)))
            values["humidity"].append(float(env.get("relativeHumidity", 0.0)))
            values["co2"].append(float(env.get("co2", 0.0)))
            values["people"].append(float(env.get("peopleCount", 0.0)))
        if noise:
            values["noise"].append(float(noise.get("LAeq", 0.0)))
        if crowd:
            values["occupancy"].append(float(crowd.get("occupancy", 0.0)))

    def avg(lst: List[float]) -> float:
        return round(sum(lst) / len(lst), 2) if lst else 0.0

    status = "optimal"
    if any(s == "critical" for s in statuses):
        status = "critical"
    elif any(s == "attention" for s in statuses):
        status = "attention"

    return {
        "status": status,
        "avgTemperature": avg(values["temperature"]),
        "avgHumidity": avg(values["humidity"]),
        "avgCo2": avg(values["co2"]),
        "avgNoise": avg(values["noise"]),
        "avgOccupancy": avg(values["occupancy"]),
        "peopleCount": int(sum(values["people"])),
        "roomsCount": len(rooms),
    }


def ql_attr_series(entity_id: str, attr: str, last_n: int = 200) -> List[Dict]:
    endpoint = f"{QL_URL.rstrip('/')}/v2/entities/{entity_id}/attrs/{attr}"
    headers = {
        "Accept": "application/json",
        "Fiware-Service": "openiot",
        "Fiware-ServicePath": "/",
    }
    try:
        response = requests.get(endpoint, headers=headers, params={"lastN": last_n}, timeout=12)
        if response.status_code >= 400:
            return []
        data = response.json()

        if isinstance(data, dict) and "values" in data and isinstance(data["values"], list):
            points = []
            indexes = data.get("index", [])
            for idx, value in enumerate(data["values"]):
                ts = indexes[idx] if idx < len(indexes) else None
                points.append({"timestamp": ts, "value": value})
            return points

        if isinstance(data, dict):
            # Formato alternativo: {attr: [{recvTime, attrValue}, ...]}
            for key, val in data.items():
                if isinstance(val, list):
                    points = []
                    for row in val:
                        if isinstance(row, dict):
                            points.append(
                                {
                                    "timestamp": row.get("recvTime") or row.get("index") or row.get("timestamp"),
                                    "value": row.get("attrValue")
                                    if "attrValue" in row
                                    else row.get("value"),
                                }
                            )
                    if points:
                        return points
    except Exception:  # noqa: BLE001
        return []
    return []


def to_float(value, default=0.0) -> float:
    try:
        return float(value)
    except Exception:  # noqa: BLE001
        return default


def series_for_room(room_id: str, range_key: str = "24h") -> Dict[str, List[Dict]]:
    mapping = {"1h": 20, "6h": 90, "12h": 150, "24h": 300, "7d": 900, "30d": 1500}
    n = mapping.get(range_key, 300)

    room = resolve_room(room_id)
    rc = room["id"].split(":")[-1]

    env_id = f"urn:ngsi-ld:IndoorEnvironmentObserved:{rc}"
    noise_id = f"urn:ngsi-ld:NoiseLevelObserved:{rc}"
    crowd_id = f"urn:ngsi-ld:CrowdFlowObserved:{rc}"

    data = {
        "temperature": ql_attr_series(env_id, "temperature", n),
        "relativeHumidity": ql_attr_series(env_id, "relativeHumidity", n),
        "co2": ql_attr_series(env_id, "co2", n),
        "illuminance": ql_attr_series(env_id, "illuminance", n),
        "peopleCount": ql_attr_series(env_id, "peopleCount", n),
        "LAeq": ql_attr_series(noise_id, "LAeq", n),
        "occupancy": ql_attr_series(crowd_id, "occupancy", n),
    }

    # Fallback derivado del estado actual si QuantumLeap aun no tiene datos.
    if not any(data.values()):
        env_by_room, noise_by_room, crowd_by_room = room_latest_entities()
        env = env_by_room.get(room["id"], {})
        noise = noise_by_room.get(room["id"], {})
        crowd = crowd_by_room.get(room["id"], {})
        ts = utc_now()
        data = {
            "temperature": [{"timestamp": ts, "value": env.get("temperature", 21.0)}],
            "relativeHumidity": [{"timestamp": ts, "value": env.get("relativeHumidity", 50.0)}],
            "co2": [{"timestamp": ts, "value": env.get("co2", 700.0)}],
            "illuminance": [{"timestamp": ts, "value": env.get("illuminance", 120.0)}],
            "peopleCount": [{"timestamp": ts, "value": env.get("peopleCount", 0)}],
            "LAeq": [{"timestamp": ts, "value": noise.get("LAeq", 48.0)}],
            "occupancy": [{"timestamp": ts, "value": crowd.get("occupancy", 0.0)}],
        }
    return data


def fit_models():
    global risk_model, failure_model

    # Modelo de riesgo de degradacion de obra.
    n = 5000
    rng = np.random.default_rng(42)
    temp_dev = rng.uniform(0, 8, n)
    hum_dev = rng.uniform(0, 20, n)
    co2_dev = rng.uniform(0, 900, n)
    lux_dev = rng.uniform(0, 250, n)
    noise_dev = rng.uniform(0, 35, n)
    X = np.column_stack([temp_dev, hum_dev, co2_dev, lux_dev, noise_dev])
    y = (
        0.24 * (temp_dev / 8)
        + 0.24 * (hum_dev / 20)
        + 0.24 * (co2_dev / 900)
        + 0.14 * (lux_dev / 250)
        + 0.14 * (noise_dev / 35)
        + rng.normal(0, 0.03, n)
    )
    y = np.clip(y, 0.0, 1.0)
    risk_model = RandomForestRegressor(n_estimators=120, random_state=42)
    risk_model.fit(X, y)

    # Modelo de prediccion de fallo de dispositivo (7 dias de tendencia).
    n2 = 3000
    battery_slope = rng.uniform(-0.08, 0.01, n2)
    latency_slope = rng.uniform(-30, 160, n2)
    battery_now = rng.uniform(0.02, 1.0, n2)
    latency_now = rng.uniform(40, 2500, n2)
    X2 = np.column_stack([battery_slope, latency_slope, battery_now, latency_now])

    z = (
        -18 * battery_slope
        + 0.009 * latency_slope
        + 1.2 * (1.0 - battery_now)
        + 0.0012 * latency_now
        - 1.5
    )
    p = 1 / (1 + np.exp(-z))
    y2 = (p > 0.52).astype(int)

    failure_model = LogisticRegression(max_iter=1200)
    failure_model.fit(X2, y2)


