@app.route("/api/centers")
def api_centers():
    payload = []
    for center in MUSEUMS:
        snap = center_snapshot(center["id"])
        payload.append(
            {
                "id": center["id"],
                "code": center["code"],
                "name": center["name"],
                "type": center["museumType"][0],
