    for entity in data:
        parsed = normalize_entity(entity)
        e_type = parsed.get("type")
        processed += 1

        socketio.emit("update", {"type": e_type, "entity": parsed})
        socketio.emit(f"entity:{e_type}", parsed)

        if e_type == "Alert":
            socketio.emit("alerts", parsed)
        if e_type in {"Actuator", "Device"}:
            socketio.emit("devices", parsed)

        if e_type == "IndoorEnvironmentObserved":
            room_id = parsed.get("refPointOfInterest")
            if room_id:
                evaluate_thresholds(room_id, parsed, noise_by_room.get(room_id), crowd_by_room.get(room_id))
                refresh_artwork_risks()

    return jsonify({"received": processed, "timestamp": utc_now()})


@socketio.on("connect")
def socket_connect():
    socketio.emit("update", {"event": "connected", "timestamp": utc_now()})


def startup_checks():
    fit_models()
    try:
        _ = orion_list(limit=1)
        print("[backend] Orion conectado")
    except Exception as exc:  # noqa: BLE001
        print(f"[backend] Aviso Orion no disponible al arranque: {exc}")


if __name__ == "__main__":
    startup_checks()
    socketio.run(app, host="0.0.0.0", port=5000)
"}

{"filePath":"/Users/mangelvilarino/Desktop/2-CUAT-4/GDEI/PRACTICAS/GDEI-P3/backend/static/css/style.css","content":"@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;700&family=Literata:opsz,wght@7..72,500;7..72,700&display=swap');

:root {
  --font-ui: 'Space Grotesk', sans-serif;
  --font-display: 'Literata', serif;

  --bg: #f2efe8;
  --panel: #fff9ef;
  --text: #1d2627;
  --muted: #516266;
  --accent: #0e7c74;
  --accent-2: #d27d3f;
  --danger: #b5443c;
  --warn: #a86b18;
  --ok: #26875f;

  --border: #d7cfbe;
  --shadow: 0 10px 30px rgba(29, 38, 39, 0.12);
  --radius: 14px;
}

[data-theme="dark"] {
  --bg: #101919;
  --panel: #172323;
  --text: #e9f0ec;
  --muted: #99ada7;
  --accent: #45c5bb;
  --accent-2: #f0a15d;
  --danger: #ea7164;
  --warn: #f0bb62;
  --ok: #51d494;

  --border: #28403e;
  --shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: var(--font-ui);
  color: var(--text);
  background:
    radial-gradient(circle at 8% 12%, rgba(14, 124, 116, 0.18) 0, transparent 30%),
    radial-gradient(circle at 92% 6%, rgba(210, 125, 63, 0.16) 0, transparent 35%),
    linear-gradient(180deg, var(--bg), color-mix(in srgb, var(--bg) 88%, #000 12%));
  min-height: 100vh;
}

a {
  color: inherit;
  text-decoration: none;
}

.app-shell {
  width: min(1320px, 94vw);
  margin: 18px auto 28px;
}

.topbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 14px 18px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: color-mix(in srgb, var(--panel) 94%, transparent);
  backdrop-filter: blur(8px);
  box-shadow: var(--shadow);
  position: sticky;
  top: 10px;
  z-index: 20;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
}

.brand-mark {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  background: linear-gradient(145deg, var(--accent), var(--accent-2));
  box-shadow: 0 4px 18px color-mix(in srgb, var(--accent) 55%, transparent);
}

.brand h1 {
  margin: 0;
  font-family: var(--font-display);
  font-size: 1.2rem;
  letter-spacing: 0.02em;
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.btn,
select,
input,
textarea {
  font: inherit;
}

.btn {
  border: 1px solid var(--border);
  background: var(--panel);
  color: var(--text);
  padding: 8px 12px;
  border-radius: 10px;
  cursor: pointer;
  transition: transform 0.2s ease, background 0.2s ease;
}

.btn:hover {
  transform: translateY(-1px);
}

.btn-primary {
  background: linear-gradient(145deg, var(--accent), color-mix(in srgb, var(--accent) 70%, #fff 30%));
  color: #fff;
  border: none;
}

.nav-links {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.nav-link {
  padding: 6px 10px;
  border-radius: 8px;
  border: 1px solid transparent;
  color: var(--muted);
}

.nav-link.active,
.nav-link:hover {
  border-color: var(--border);
  color: var(--text);
  background: color-mix(in srgb, var(--accent) 8%, var(--panel));
}

.grid {
  display: grid;
  gap: 14px;
}

.grid-2 {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.grid-3 {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.grid-4 {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.card {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 14px;
  box-shadow: var(--shadow);
}

.card h2,
.card h3,
.card h4 {
  font-family: var(--font-display);
  margin-top: 0;
}

.kpi {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.kpi .value {
  font-size: 1.55rem;
  font-weight: 700;
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.82rem;
  border-radius: 999px;
  padding: 3px 10px;
  border: 1px solid transparent;
}

.badge.optimal {
  color: var(--ok);
  background: color-mix(in srgb, var(--ok) 13%, transparent);
}

.badge.attention {
  color: var(--warn);
  background: color-mix(in srgb, var(--warn) 13%, transparent);
}

.badge.critical {
  color: var(--danger);
  background: color-mix(in srgb, var(--danger) 13%, transparent);
}

.table-wrap {
  overflow: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th,
td {
  border-bottom: 1px solid var(--border);
  padding: 8px;
  text-align: left;
  font-size: 0.92rem;
}

th {
  color: var(--muted);
  font-weight: 500;
}

.leaflet-map,
.chart-wrap,
.three-wrap,
.grafana-frame {
  border: 1px solid var(--border);
  border-radius: 12px;
  overflow: hidden;
  background: color-mix(in srgb, var(--panel) 96%, #000 4%);
}

.leaflet-map {
  height: 420px;
}

.chart-wrap {
  min-height: 260px;
  padding: 10px;
}

.three-wrap {
  height: 520px;
}

.grafana-frame {
  height: 460px;
}

iframe {
  width: 100%;
  height: 100%;
  border: none;
}

.alert-list {
  max-height: 360px;
  overflow: auto;
  display: grid;
  gap: 8px;
}

.alert-item {
  border: 1px solid var(--border);
  border-left: 5px solid var(--warn);
  border-radius: 10px;
  padding: 8px;
  background: color-mix(in srgb, var(--panel) 92%, #fff 8%);
}

.alert-item.critical {
  border-left-color: var(--danger);
}

.alert-item.optimal {
  border-left-color: var(--ok);
}

.fade-up {
  animation: fadeUp 0.45s ease both;
}

.stagger > * {
  opacity: 0;
  transform: translateY(10px);
  animation: fadeUp 0.4s ease forwards;
}

.stagger > *:nth-child(1) { animation-delay: 0.02s; }
.stagger > *:nth-child(2) { animation-delay: 0.06s; }
.stagger > *:nth-child(3) { animation-delay: 0.1s; }
.stagger > *:nth-child(4) { animation-delay: 0.14s; }
.stagger > *:nth-child(5) { animation-delay: 0.18s; }
.stagger > *:nth-child(6) { animation-delay: 0.22s; }

@keyframes fadeUp {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.controls-row {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  align-items: center;
}

.input,
select,
textarea {
  border: 1px solid var(--border);
  border-radius: 9px;
  background: var(--panel);
  color: var(--text);
  padding: 8px 10px;
}

.split {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 14px;
}

.pill {
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 4px 10px;
  color: var(--muted);
  font-size: 0.84rem;
}

.small {
  font-size: 0.83rem;
  color: var(--muted);
}

.visitor-shell {
  width: min(760px, 94vw);
  margin: 18px auto;
}

.chat-box {
  display: grid;
  gap: 8px;
  max-height: 260px;
  overflow: auto;
  padding: 8px;
  border: 1px solid var(--border);
  border-radius: 12px;
}

.chat-msg {
  border-radius: 10px;
  padding: 8px 10px;
  background: color-mix(in srgb, var(--accent) 10%, var(--panel));
}

.chat-msg.bot {
  background: color-mix(in srgb, var(--accent-2) 16%, var(--panel));
}

@media (max-width: 1024px) {
  .grid-4 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .split {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 720px) {
  .app-shell {
    width: 96vw;
  }

  .topbar {
    position: static;
    padding: 12px;
  }

  .grid-3,
  .grid-2,
  .grid-4 {
    grid-template-columns: 1fr;
  }

  .leaflet-map {
    height: 320px;
  }

  .three-wrap {
    height: 380px;
  }
}
"}

{"filePath":"/Users/mangelvilarino/Desktop/2-CUAT-4/GDEI/PRACTICAS/GDEI-P3/backend/static/js/common.js","content":"const AURA = {
  lang: localStorage.getItem('aura-lang') || 'es',
  theme: localStorage.getItem('aura-theme') || 'light',
  socket: null,
  t: {
    es: {
      dashboard: 'Dashboard',
      centers: 'Centros',
      control: 'Control',
      light: 'Claro',
      dark: 'Oscuro',
      alerts: 'Alertas',
      resolve: 'Resolver',
      loading: 'Cargando...',
      noData: 'Sin datos',
      visitor: 'Visitante',
      send: 'Enviar',
      room: 'Sala',
      status: 'Estado',
      comfort: 'Confort',
      temperature: 'Temperatura',
      humidity: 'Humedad',
      co2: 'CO2',
      occupancy: 'Aforo',
    },
    en: {
      dashboard: 'Dashboard',
      centers: 'Centers',
      control: 'Control',
      light: 'Light',
      dark: 'Dark',
      alerts: 'Alerts',
      resolve: 'Resolve',
      loading: 'Loading...',
      noData: 'No data',
      visitor: 'Visitor',
      send: 'Send',
      room: 'Room',
      status: 'Status',
      comfort: 'Comfort',
      temperature: 'Temperature',
      humidity: 'Humidity',
      co2: 'CO2',
      occupancy: 'Occupancy',
    },
  },
};

function tr(key) {
  return (AURA.t[AURA.lang] && AURA.t[AURA.lang][key]) || key;
}

function setTheme(theme) {
  AURA.theme = theme;
  localStorage.setItem('aura-theme', theme);
  document.documentElement.setAttribute('data-theme', theme);
  const btn = document.getElementById('themeToggle');
  if (btn) {
    btn.textContent = theme === 'dark' ? tr('light') : tr('dark');
  }
}

function setLang(lang) {
  AURA.lang = lang;
  localStorage.setItem('aura-lang', lang);
  document.querySelectorAll('[data-i18n]').forEach((el) => {
    el.textContent = tr(el.getAttribute('data-i18n'));
  });
  const btn = document.getElementById('langToggle');
  if (btn) {
    btn.textContent = lang.toUpperCase();
  }
  setTheme(AURA.theme);
}

async function apiGet(path) {
  const response = await fetch(path);
  if (!response.ok) {
    const text = await response.text();
    throw new Error(text || `HTTP ${response.status}`);
  }
  return response.json();
}

async function apiSend(path, method, body) {
  const response = await fetch(path, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body ? JSON.stringify(body) : undefined,
  });
  if (!response.ok) {
    const text = await response.text();
    throw new Error(text || `HTTP ${response.status}`);
  }
  return response.json();
}

function statusBadge(status) {
  const cls = status || 'attention';
  return `<span class="badge ${cls}">${cls}</span>`;
}

function ensureSocket() {
  if (AURA.socket) return AURA.socket;
  AURA.socket = io();
  return AURA.socket;
}

function formatNumber(val, digits = 1) {
  if (val === null || val === undefined || Number.isNaN(Number(val))) return '-';
  return Number(val).toFixed(digits);
}

function activeNav() {
  const page = document.body.getAttribute('data-page');
  document.querySelectorAll('.nav-link').forEach((el) => {
    if (el.dataset.page === page) el.classList.add('active');
  });
}

function wireToolbar() {
  const themeBtn = document.getElementById('themeToggle');
  const langBtn = document.getElementById('langToggle');

  if (themeBtn) {
    themeBtn.addEventListener('click', () => setTheme(AURA.theme === 'dark' ? 'light' : 'dark'));
  }
  if (langBtn) {
    langBtn.addEventListener('click', () => setLang(AURA.lang === 'es' ? 'en' : 'es'));
  }
}

function initCommon() {
  setTheme(AURA.theme);
  setLang(AURA.lang);
  wireToolbar();
  activeNav();
}

document.addEventListener('DOMContentLoaded', initCommon);
"}

{"filePath":"/Users/mangelvilarino/Desktop/2-CUAT-4/GDEI/PRACTICAS/GDEI-P3/backend/static/js/dashboard.js","content":"let dashboardMap;
let trendChart;

function markerColor(status) {
  if (status === 'critical') return '#b5443c';
  if (status === 'attention') return '#a86b18';
  return '#26875f';
}

function mapIcon(status) {
  const color = markerColor(status);
  return L.divIcon({
    className: 'custom-pin',
    html: `<div style="width:18px;height:18px;border-radius:50%;background:${color};border:2px solid #fff;box-shadow:0 0 0 3px ${color}55"></div>`,
    iconSize: [18, 18],
  });
}

async function loadSummary() {
  const data = await apiGet('/api/dashboard/summary');
  const kpi = data.kpis;
  document.getElementById('kpiVisitors').textContent = kpi.visitorsTotal;
  document.getElementById('kpiRooms').textContent = `${kpi.roomsOptimalPct}%`;
  document.getElementById('kpiRisk').textContent = kpi.artworksAtRisk;
  document.getElementById('kpiSensors').textContent = `${kpi.sensorsActive}/${kpi.sensorsTotal}`;
}

async function loadCentersMap() {
  const centers = await apiGet('/api/centers');
  if (!dashboardMap) {
    dashboardMap = L.map('globalMap').setView([43.3705, -8.4075], 13);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19,
      attribution: '&copy; OpenStreetMap contributors',
    }).addTo(dashboardMap);
  }

  if (window._centerLayer) {
    window._centerLayer.forEach((m) => m.remove());
  }
  window._centerLayer = [];

  centers.forEach((center) => {
    const coords = center.location.coordinates;
    const marker = L.marker([coords[1], coords[0]], { icon: mapIcon(center.status) }).addTo(dashboardMap);
    marker.bindPopup(`
      <strong>${center.name}</strong><br/>
      <img src="${center.image}" alt="${center.name}" style="width:180px;border-radius:8px;margin-top:6px"/><br/>
      Temp: ${formatNumber(center.snapshot.avgTemperature)} C<br/>
      CO2: ${formatNumber(center.snapshot.avgCo2)} ppm<br/>
      Estado: ${center.status}
    `);
    marker.on('click', () => {
      window.location.href = `/center/${center.code}`;
    });
    window._centerLayer.push(marker);
  });
}

async function loadTrend() {
  const centers = await apiGet('/api/centers');
  const centerData = await Promise.all(
    centers.map((center) => apiGet(`/api/centers/${center.code}/trend?range=12h`))
  );

  const allTemp = [];
  const allPeople = [];
  centerData.forEach((d) => {
    d.temperature.forEach((p) => allTemp.push(Number(p.value)));
    d.peopleCount.forEach((p) => allPeople.push(Number(p.value)));
  });

  const labels = Array.from({ length: 12 }, (_, i) => `${i + 1}h`);
  const tempData = labels.map((_, i) => {
    const idx = Math.floor((allTemp.length * i) / labels.length);
    return Number(allTemp[idx] || 0);
  });
  const peopleData = labels.map((_, i) => {
    const idx = Math.floor((allPeople.length * i) / labels.length);
    return Number(allPeople[idx] || 0);
  });

  if (trendChart) trendChart.destroy();
  const ctx = document.getElementById('trendChart');
  trendChart = new Chart(ctx, {
    type: 'line',
    data: {
      labels,
      datasets: [
        {
          label: tr('temperature'),
          data: tempData,
          borderColor: '#0e7c74',
          backgroundColor: '#0e7c7422',
          tension: 0.28,
          yAxisID: 'y',
        },
        {
          label: tr('occupancy'),
          data: peopleData,
          borderColor: '#d27d3f',
          backgroundColor: '#d27d3f22',
          tension: 0.25,
          yAxisID: 'y1',
        },
      ],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: 'index', intersect: false },
      scales: {
        y: { position: 'left', title: { display: true, text: 'C' } },
        y1: { position: 'right', grid: { drawOnChartArea: false }, title: { display: true, text: 'people' } },
      },
    },
  });
}

function renderAlerts(alerts) {
  const panel = document.getElementById('alertsPanel');
  if (!alerts.length) {
    panel.innerHTML = `<div class="small">${tr('noData')}</div>`;
    return;
  }
  panel.innerHTML = alerts
    .slice(0, 30)
    .map(
      (a) => `
      <div class="alert-item ${a.severity === 'critical' ? 'critical' : ''}">
        <div style="display:flex;justify-content:space-between;gap:8px;align-items:start">
          <div>
            <strong>${a.subCategory || 'Alert'}</strong><br/>
            <span class="small">${a.description || ''}</span>
          </div>
          <button class="btn" data-alert-id="${a.id}">${tr('resolve')}</button>
        </div>
      </div>
    `
    )
    .join('');

  panel.querySelectorAll('button[data-alert-id]').forEach((btn) => {
    btn.addEventListener('click', async () => {
      const id = btn.getAttribute('data-alert-id');
      await apiSend(`/api/alerts/${encodeURIComponent(id)}/resolve`, 'PATCH');
      await loadAlerts();
    });
  });
}

async function loadAlerts() {
  const alerts = await apiGet('/api/admin/alerts?status=open');
  renderAlerts(alerts);
}

function loadMermaid() {
  const el = document.getElementById('modelMermaid');
  const code = `graph TD\nMuseum-->Room\nRoom-->Artwork\nRoom-->Device\nRoom-->Actuator\nDevice-->IndoorEnvironmentObserved\nDevice-->NoiseLevelObserved\nDevice-->CrowdFlowObserved\nAlert-->Room`;
  el.textContent = code;
  mermaid.initialize({ startOnLoad: false, theme: 'default', securityLevel: 'loose' });
  mermaid.run({ nodes: [el] });

  const toggle = document.getElementById('toggleMermaid');
  const body = document.getElementById('mermaidBody');
  toggle.addEventListener('click', () => {
    body.style.display = body.style.display === 'none' ? 'block' : 'none';
  });
}

async function bootDashboard() {
  await Promise.all([loadSummary(), loadCentersMap(), loadTrend(), loadAlerts()]);
  loadMermaid();

  const socket = ensureSocket();
  socket.on('alerts', () => loadAlerts());
  socket.on('update', () => loadSummary());
}

document.addEventListener('DOMContentLoaded', () => {
  if (document.body.getAttribute('data-page') === 'dashboard') {
    bootDashboard().catch((err) => console.error(err));
  }
});
"}

{"filePath":"/Users/mangelvilarino/Desktop/2-CUAT-4/GDEI/PRACTICAS/GDEI-P3/backend/static/js/centers.js","content":"let centersCache = [];

function occupancyBucket(v) {
  if (v < 0.35) return 'free';
  if (v <= 0.7) return 'moderate';
  return 'congested';
}

async function loadCenters() {
  centersCache = await apiGet('/api/centers');
  renderCenters();
  await renderSparklines();
}

function renderCenters() {
  const typeFilter = document.getElementById('filterType').value;
  const statusFilter = document.getElementById('filterStatus').value;
  const occFilter = document.getElementById('filterOccupancy').value;

  const data = centersCache.filter((c) => {
    if (typeFilter && !c.type.includes(typeFilter)) return false;
    if (statusFilter && c.status !== statusFilter) return false;
    if (occFilter && occupancyBucket(c.snapshot.avgOccupancy) !== occFilter) return false;
    return true;
  });

  const grid = document.getElementById('centersGrid');
  grid.innerHTML = data
    .map(
      (c) => `
      <article class="card fade-up" id="card-${c.code}">
        <img src="${c.image}" alt="${c.name}" style="width:100%;height:180px;object-fit:cover;border-radius:10px"/>
        <div style="margin-top:10px;display:flex;justify-content:space-between;align-items:center;gap:8px">
          <h3 style="margin:0">${c.name}</h3>
          ${statusBadge(c.status)}
        </div>
        <p class="small">${c.type}</p>
        <div class="grid grid-2">
          <div>${tr('temperature')}: <strong>${formatNumber(c.snapshot.avgTemperature)} C</strong></div>
          <div>${tr('humidity')}: <strong>${formatNumber(c.snapshot.avgHumidity)}%</strong></div>
          <div>${tr('co2')}: <strong>${formatNumber(c.snapshot.avgCo2, 0)} ppm</strong></div>
          <div>${tr('occupancy')}: <strong>${Math.round(c.snapshot.avgOccupancy * 100)}%</strong></div>
        </div>
        <div class="chart-wrap" style="margin-top:10px;height:130px"><canvas id="spark-${c.code}"></canvas></div>
        <div style="display:flex;justify-content:flex-end;margin-top:10px">
          <a class="btn btn-primary" href="/center/${c.code}">Ver detalle</a>
        </div>
      </article>
    `
    )
    .join('');
}

async function renderSparklines() {
  const jobs = centersCache.map(async (c) => {
    try {
      const trend = await apiGet(`/api/centers/${c.code}/trend?range=1h`);
      const temp = trend.temperature.slice(-20).map((p) => Number(p.value || 0));
      const labels = temp.map((_, idx) => idx + 1);
      const ctx = document.getElementById(`spark-${c.code}`);
      if (!ctx) return;
      new Chart(ctx, {
        type: 'line',
        data: {
          labels,
          datasets: [
            {
              data: temp,
              borderColor: '#0e7c74',
              backgroundColor: '#0e7c741a',
              borderWidth: 2,
              fill: true,
              pointRadius: 0,
              tension: 0.25,
            },
          ],
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: { legend: { display: false } },
          scales: { x: { display: false }, y: { display: false } },
        },
      });
    } catch (err) {
      console.error(err);
    }
  });
  await Promise.all(jobs);
}

function wireFilters() {
  ['filterType', 'filterStatus', 'filterOccupancy'].forEach((id) => {
    document.getElementById(id).addEventListener('change', () => {
      renderCenters();
      renderSparklines();
    });
  });
}

document.addEventListener('DOMContentLoaded', () => {
  if (document.body.getAttribute('data-page') !== 'centers') return;
  wireFilters();
  loadCenters().catch((err) => console.error(err));
  ensureSocket().on('update', () => loadCenters());
});
"}

{"filePath":"/Users/mangelvilarino/Desktop/2-CUAT-4/GDEI/PRACTICAS/GDEI-P3/backend/static/js/center_detail.js","content":"let gaugeCharts = {};
let historyChart;

function centerCodeFromPath() {
  const parts = window.location.pathname.split('/').filter(Boolean);
  return parts[1];
}

function gaugeConfig(value, max, color) {
  return {
    type: 'doughnut',
    data: {
      labels: ['value', 'rest'],
      datasets: [
        {
          data: [Math.max(0, Math.min(max, value)), Math.max(0, max - value)],
          backgroundColor: [color, '#d8d8d833'],
          borderWidth: 0,
          cutout: '72%',
        },
      ],
    },
    options: {
      plugins: { legend: { display: false }, tooltip: { enabled: false } },
      responsive: true,
      maintainAspectRatio: false,
    },
  };
}

function upsertGauge(id, value, max, color, label) {
  const ctx = document.getElementById(id);
  if (!ctx) return;
  if (gaugeCharts[id]) gaugeCharts[id].destroy();
  gaugeCharts[id] = new Chart(ctx, gaugeConfig(value, max, color));
  document.getElementById(`${id}-value`).textContent = `${formatNumber(value)} ${label}`;
}

async function loadCenterSnapshot(code) {
  const center = await apiGet(`/api/centers/${code}`);
  const snap = center.snapshot;
  document.getElementById('centerTitle').textContent = center.name;
  document.getElementById('centerStatus').innerHTML = statusBadge(snap.status);

  upsertGauge('gTemp', snap.avgTemperature, 35, '#0e7c74', 'C');
  upsertGauge('gHum', snap.avgHumidity, 100, '#3d9ecf', '%');
  upsertGauge('gCo2', snap.avgCo2, 1800, '#d27d3f', 'ppm');
  upsertGauge('gNoise', snap.avgNoise, 100, '#7c5bd6', 'dB');
  upsertGauge('gOcc', snap.avgOccupancy * 100, 100, '#a86b18', '%');
}

async function loadRooms(code) {
  const rooms = await apiGet(`/api/centers/${code}/rooms`);
  const list = document.getElementById('roomsList');
  list.innerHTML = rooms
    .map(
      (r) => `
      <div class="card" style="padding:10px">
        <div style="display:flex;justify-content:space-between;gap:8px;align-items:center">
          <strong>${r.name}</strong>
          ${statusBadge(r.status)}
        </div>
        <div class="small">${tr('occupancy')}: ${Math.round((Number(r.current.occupancy || 0)) * 100)}%</div>
        <a class="btn" href="/room/${encodeURIComponent(r.id)}" style="margin-top:8px">Detalle sala</a>
      </div>
    `
    )
    .join('');
}

async function loadRiskArtworks(code) {
  const arts = await apiGet(`/api/centers/${code}/artworks/at-risk`);
  const list = document.getElementById('riskList');
  list.innerHTML = arts.length
    ? arts
        .slice(0, 12)
        .map(
          (a) => `<div class="alert-item ${Number(a.degradationRisk) > 0.8 ? 'critical' : ''}"><strong>${a.name}</strong><br/><span class="small">${a.artist} · riesgo ${formatNumber(a.degradationRisk, 3)}</span></div>`
        )
        .join('')
    : `<div class="small">${tr('noData')}</div>`;
}

async function loadHistory(code) {
  const range = document.getElementById('rangeSelect').value;
  const history = await apiGet(`/api/centers/${code}/history?range=${range}`);
  const labels = history.temperature.map((p) => p.timestamp || 't');

  const dataSets = [
    { key: 'temperature', color: '#0e7c74', label: tr('temperature') },
    { key: 'relativeHumidity', color: '#3d9ecf', label: tr('humidity') },
    { key: 'co2', color: '#d27d3f', label: tr('co2') },
    { key: 'LAeq', color: '#7c5bd6', label: 'LAeq' },
    { key: 'peopleCount', color: '#a86b18', label: tr('occupancy') },
  ];

  const datasets = dataSets.map((s) => ({
    label: s.label,
    data: history[s.key].map((p) => Number(p.value || 0)),
    borderColor: s.color,
    backgroundColor: `${s.color}22`,
    fill: false,
    tension: 0.2,
    pointRadius: 0,
  }));

  if (historyChart) historyChart.destroy();
  historyChart = new Chart(document.getElementById('historyChart'), {
    type: 'line',
    data: { labels, datasets },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: { legend: { position: 'bottom' } },
    },
  });
}

async function loadActuators(code) {
  const acts = await apiGet(`/api/centers/${code}/actuators`);
  const wrap = document.getElementById('actuatorPanel');
  wrap.innerHTML = acts
    .map(
      (a) => `
      <div class="card" style="padding:10px">
        <div style="display:flex;justify-content:space-between;align-items:center;gap:8px">
          <strong>${a.name || a.id}</strong>
          <span class="pill">${a.status || 'off'}</span>
        </div>
        <div class="controls-row" style="margin-top:8px">
          <button class="btn btn-primary" data-act="${a.id}" data-cmd="on">ON</button>
          <button class="btn" data-act="${a.id}" data-cmd="off">OFF</button>
        </div>
      </div>
    `
    )
    .join('');

  wrap.querySelectorAll('button[data-act]').forEach((btn) => {
    btn.addEventListener('click', async () => {
      const id = btn.getAttribute('data-act');
      const cmd = btn.getAttribute('data-cmd');
      await apiSend(`/api/actuators/${encodeURIComponent(id)}/command`, 'POST', { command: cmd });
      await loadActuators(code);
    });
  });
}

async function loadGrafana(code) {
  const info = await apiGet(`/api/grafana/center/${code}`);
  document.getElementById('grafanaFrame').src = info.embed;
}

async function bootCenterDetail() {
  const code = centerCodeFromPath();
  await Promise.all([
    loadCenterSnapshot(code),
    loadRooms(code),
    loadRiskArtworks(code),
    loadHistory(code),
    loadActuators(code),
    loadGrafana(code),
  ]);

  document.getElementById('rangeSelect').addEventListener('change', () => loadHistory(code));

  const socket = ensureSocket();
  socket.on('update', () => loadCenterSnapshot(code));
  socket.on('actuators', () => loadActuators(code));
  socket.on('alerts', () => loadRiskArtworks(code));
}

document.addEventListener('DOMContentLoaded', () => {
  if (document.body.getAttribute('data-page') !== 'center-detail') return;
  bootCenterDetail().catch((err) => console.error(err));
});
"}

{"filePath":"/Users/mangelvilarino/Desktop/2-CUAT-4/GDEI/PRACTICAS/GDEI-P3/backend/static/js/twin3d.js","content":"let scene;
let camera;
let renderer;
let controls;
let raycaster;
let mouse;
let roomMeshes = new Map();
let roomValues = {};
let centerCode;
let selectedRoomId = null;

function colorForValue(variable, value) {
  const clamp = (v) => Math.max(0, Math.min(1, v));
  let n = 0;
  if (variable === 'temperature') n = clamp((value - 16) / 12);
  if (variable === 'co2') n = clamp((value - 500) / 1200);
  if (variable === 'relativeHumidity') n = clamp((value - 35) / 35);
  if (variable === 'LAeq') n = clamp((value - 40) / 35);
  if (variable === 'occupancy') n = clamp(value);

  const r = Math.round(20 + 210 * n);
  const g = Math.round(180 - 100 * n);
  const b = Math.round(120 - 90 * n);
  return new THREE.Color(`rgb(${r},${g},${b})`);
}

function centerCodeFromPath() {
  const parts = window.location.pathname.split('/').filter(Boolean);
  return parts[1];
}

function initScene() {
  scene = new THREE.Scene();
  scene.background = new THREE.Color('#0d1417');

  camera = new THREE.PerspectiveCamera(58, 1, 0.1, 1200);
  camera.position.set(18, 24, 30);

  renderer = new THREE.WebGLRenderer({ antialias: true });
  const wrap = document.getElementById('twinCanvas');
  renderer.setSize(wrap.clientWidth, wrap.clientHeight);
  wrap.innerHTML = '';
  wrap.appendChild(renderer.domElement);

  controls = new THREE.OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;

  const amb = new THREE.AmbientLight(0xffffff, 0.7);
  const dir = new THREE.DirectionalLight(0xffffff, 0.8);
  dir.position.set(12, 24, 8);
  scene.add(amb, dir);

  const grid = new THREE.GridHelper(140, 28, 0x44555b, 0x2b383d);
  scene.add(grid);

  raycaster = new THREE.Raycaster();
  mouse = new THREE.Vector2();

  renderer.domElement.addEventListener('click', onClickRoom);
  window.addEventListener('resize', onResize);
}

function onResize() {
  const wrap = document.getElementById('twinCanvas');
  if (!renderer || !camera || !wrap) return;
  camera.aspect = wrap.clientWidth / wrap.clientHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(wrap.clientWidth, wrap.clientHeight);
}

function makeRoomMesh(room) {
  const w = Math.max(4, Math.min(16, room.area / 65));
  const h = 2.8;
  const d = Math.max(4, Math.min(14, room.capacity / 70));
  const geom = new THREE.BoxGeometry(w, h, d);
  const mat = new THREE.MeshStandardMaterial({ color: '#3a8084', metalness: 0.1, roughness: 0.65 });
  const mesh = new THREE.Mesh(geom, mat);
  mesh.position.set(room.x, room.y + h / 2, room.z);
  mesh.userData = room;
  scene.add(mesh);

  const label = makeLabel(room.name);
  label.position.set(room.x, room.y + h + 1.4, room.z);
  scene.add(label);

  const sensor = new THREE.Mesh(
    new THREE.SphereGeometry(0.35, 16, 16),
    new THREE.MeshStandardMaterial({ color: '#f4b74d', emissive: '#b56914', emissiveIntensity: 0.35 })
  );
  sensor.position.set(room.x - w / 3, room.y + h + 0.6, room.z - d / 3);
  sensor.userData = { roomId: room.id, sensor: true };
  scene.add(sensor);

  roomMeshes.set(room.id, mesh);
}

function makeLabel(text) {
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 64;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#f0f4ee';
  ctx.font = '24px Space Grotesk';
  ctx.fillText(text.slice(0, 34), 10, 40);
  const texture = new THREE.CanvasTexture(canvas);
  const material = new THREE.SpriteMaterial({ map: texture, transparent: true });
  const sprite = new THREE.Sprite(material);
  sprite.scale.set(8, 1, 1);
  return sprite;
}

function makeParticles() {
  const count = 200;
  const geom = new THREE.BufferGeometry();
  const positions = new Float32Array(count * 3);
  for (let i = 0; i < count; i += 1) {
    positions[i * 3] = (Math.random() - 0.5) * 60;
    positions[i * 3 + 1] = 1 + Math.random() * 8;
    positions[i * 3 + 2] = (Math.random() - 0.5) * 60;
  }
  geom.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  const mat = new THREE.PointsMaterial({ color: '#6ed3ca', size: 0.17, transparent: true, opacity: 0.65 });
  const pts = new THREE.Points(geom, mat);
  pts.name = 'visitors-particles';
  scene.add(pts);
}

async function loadSceneData() {
  const data = await apiGet(`/api/centers/${centerCode}/3d-scene`);
  document.getElementById('sceneHint').textContent = data.shapeHint;
  data.rooms.forEach(makeRoomMesh);
  makeParticles();
}

async function refreshValues() {
  const rooms = await apiGet(`/api/centers/${centerCode}/rooms`);
  rooms.forEach((room) => {
    roomValues[room.id] = room.current || {};
  });
  paintRooms();
}

function activeVar() {
  return document.getElementById('variableSelect').value;
}

function paintRooms() {
  const variable = activeVar();
  roomMeshes.forEach((mesh, roomId) => {
    const row = roomValues[roomId] || {};
    let value = row.temperature;
    if (variable === 'co2') value = row.co2;
    if (variable === 'relativeHumidity') value = row.relativeHumidity;
    if (variable === 'LAeq') value = row.LAeq;
    if (variable === 'occupancy') value = row.occupancy;
    mesh.material.color = colorForValue(variable, Number(value || 0));
  });
}

function animate() {
  requestAnimationFrame(animate);

  const particles = scene.getObjectByName('visitors-particles');
  if (particles) {
    const pos = particles.geometry.attributes.position;
    for (let i = 0; i < pos.count; i += 1) {
      const y = pos.getY(i) + (Math.random() - 0.5) * 0.03;
      pos.setY(i, Math.max(0.5, Math.min(9.5, y)));
    }
    pos.needsUpdate = true;
  }

  controls.update();
  renderer.render(scene, camera);
}

async function openRoomPanel(roomId) {
  selectedRoomId = roomId;
  const [roomData, envData, arts] = await Promise.all([
    apiGet(`/api/rooms/${encodeURIComponent(roomId)}`),
    apiGet(`/api/rooms/${encodeURIComponent(roomId)}/environment/current`),
    apiGet(`/api/rooms/${encodeURIComponent(roomId)}/artworks`),
  ]);

  const panel = document.getElementById('roomPanel');
  panel.innerHTML = `
    <h3>${roomData.name}</h3>
    <div class="small">${roomData.description}</div>
    <div class="grid grid-2" style="margin-top:8px">
      <div>${tr('temperature')}: <strong>${formatNumber(envData.environment.temperature)} C</strong></div>
      <div>${tr('humidity')}: <strong>${formatNumber(envData.environment.relativeHumidity)}%</strong></div>
      <div>${tr('co2')}: <strong>${formatNumber(envData.environment.co2, 0)} ppm</strong></div>
      <div>${tr('occupancy')}: <strong>${formatNumber((envData.crowd.occupancy || 0) * 100, 0)}%</strong></div>
    </div>
    <h4 style="margin-top:10px">Obras</h4>
    <div class="small">${arts.slice(0, 8).map((a) => `${a.name} (${formatNumber(a.degradationRisk, 2)})`).join('<br/>') || tr('noData')}</div>
  `;
}

function onClickRoom(event) {
  const rect = renderer.domElement.getBoundingClientRect();
  mouse.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
  mouse.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
  raycaster.setFromCamera(mouse, camera);
  const intersects = raycaster.intersectObjects(Array.from(roomMeshes.values()));
  if (intersects.length) {
    const room = intersects[0].object.userData;
    openRoomPanel(room.id).catch((err) => console.error(err));
  }
}

async function runSpreadSimulation(originRoomId) {
  const data = await apiSend('/api/simulations/spread', 'POST', { room_id: originRoomId });
  data.frames.forEach((frame) => {
    setTimeout(() => {
      const mesh = roomMeshes.get(frame.roomId);
      if (!mesh) return;
      mesh.material.emissive = new THREE.Color('#37c89d');
      mesh.material.emissiveIntensity = frame.intensity;
      setTimeout(() => {
        mesh.material.emissiveIntensity = 0;
      }, 640);
    }, frame.delayMs);
  });
}

async function bootTwin() {
  centerCode = centerCodeFromPath();
  initScene();
  await loadSceneData();
  await refreshValues();
  animate();

  document.getElementById('variableSelect').addEventListener('change', paintRooms);
  document.getElementById('simulateSpread').addEventListener('click', () => {
    if (selectedRoomId) runSpreadSimulation(selectedRoomId);
  });

  setInterval(() => {
    refreshValues().catch((err) => console.error(err));
  }, 12000);

  const socket = ensureSocket();
  socket.on('update', () => refreshValues());
  socket.on('actuators', (msg) => {
    if (msg && msg.id && selectedRoomId && msg.id.includes(selectedRoomId.split(':').pop())) {
      runSpreadSimulation(selectedRoomId).catch((err) => console.error(err));
    }
  });
}

document.addEventListener('DOMContentLoaded', () => {
  if (document.body.getAttribute('data-page') !== 'twin3d') return;
  bootTwin().catch((err) => console.error(err));
});
"}

{"filePath":"/Users/mangelvilarino/Desktop/2-CUAT-4/GDEI/PRACTICAS/GDEI-P3/backend/static/js/room_artwork.js","content":"let radarChart;
let roomHistoryChart;

function roomIdFromPath() {
  const parts = window.location.pathname.split('/').filter(Boolean);
  return decodeURIComponent(parts[1]);
}

function avgReq(artworks) {
  if (!artworks.length) {
    return { temperature: 21, humidity: 50, co2: 800, illuminance: 120, noise: 55 };
  }
  const sum = artworks.reduce(
    (acc, a) => {
      const req = a.conservationRequirements || {};
      acc.temperature += (Number(req.temperatureMin || 18) + Number(req.temperatureMax || 22)) / 2;
      acc.humidity += (Number(req.humidityMin || 45) + Number(req.humidityMax || 55)) / 2;
      acc.co2 += Number(req.co2Max || 900);
      acc.illuminance += Number(req.illuminanceMax || 150);
      acc.noise += Number(req.noiseMax || 60);
      return acc;
    },
    { temperature: 0, humidity: 0, co2: 0, illuminance: 0, noise: 0 }
  );
  const n = artworks.length;
  return {
    temperature: sum.temperature / n,
    humidity: sum.humidity / n,
    co2: sum.co2 / n,
    illuminance: sum.illuminance / n,
    noise: sum.noise / n,
  };
}

function renderRadar(current, optimal) {
  const labels = [tr('temperature'), tr('humidity'), tr('co2'), 'Lux', 'dB'];
  const cVals = [
    Number(current.temperature || 0),
    Number(current.relativeHumidity || 0),
    Number(current.co2 || 0) / 10,
    Number(current.illuminance || 0),
    Number(current.LAeq || 0),
  ];
  const oVals = [optimal.temperature, optimal.humidity, optimal.co2 / 10, optimal.illuminance, optimal.noise];

  if (radarChart) radarChart.destroy();
  radarChart = new Chart(document.getElementById('roomRadar'), {
    type: 'radar',
    data: {
      labels,
      datasets: [
        {
          label: 'Actual',
          data: cVals,
          borderColor: '#0e7c74',
          backgroundColor: '#0e7c7430',
        },
        {
          label: 'Optimo',
          data: oVals,
          borderColor: '#d27d3f',
          backgroundColor: '#d27d3f28',
        },
      ],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      scales: { r: { beginAtZero: true } },
    },
  });
}

function renderArtworkTable(artworks) {
  const tbody = document.getElementById('artworksTableBody');
  tbody.innerHTML = artworks
    .map(
      (a) => `
      <tr>
        <td><input type="checkbox" data-art-id="${a.id}"/></td>
        <td><img src="${a.image}" alt="${a.name}" style="width:58px;height:42px;object-fit:cover;border-radius:6px"/></td>
        <td>${a.name}</td>
        <td>${a.artist || '-'}</td>
        <td>${a.material || '-'}</td>
        <td>${formatNumber(a.degradationRisk, 3)}</td>
      </tr>
    `
    )
    .join('');
}

function renderHistory(history) {
  const labels = history.temperature.map((p) => p.timestamp || 't');
  if (roomHistoryChart) roomHistoryChart.destroy();
  roomHistoryChart = new Chart(document.getElementById('roomHistoryChart'), {
    type: 'line',
    data: {
      labels,
      datasets: [
        {
          label: tr('temperature'),
          data: history.temperature.map((p) => Number(p.value || 0)),
          borderColor: '#0e7c74',
          pointRadius: 0,
          tension: 0.22,
        },
        {
          label: tr('humidity'),
          data: history.relativeHumidity.map((p) => Number(p.value || 0)),
          borderColor: '#3d9ecf',
          pointRadius: 0,
          tension: 0.22,
        },
        {
          label: tr('co2'),
          data: history.co2.map((p) => Number(p.value || 0)),
          borderColor: '#d27d3f',
          pointRadius: 0,
          tension: 0.22,
        },
      ],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: { legend: { position: 'bottom' } },
    },
  });
}

async function loadRoomView() {
  const roomId = roomIdFromPath();
  const [room, envCurrent, artworks, history] = await Promise.all([
    apiGet(`/api/rooms/${encodeURIComponent(roomId)}`),
    apiGet(`/api/rooms/${encodeURIComponent(roomId)}/environment/current`),
    apiGet(`/api/rooms/${encodeURIComponent(roomId)}/artworks`),
    apiGet(`/api/rooms/${encodeURIComponent(roomId)}/history?range=24h`),
  ]);

  document.getElementById('roomName').textContent = room.name;
  document.getElementById('roomMeta').textContent = `${room.area} m2 · cap ${room.capacity}`;
  document.getElementById('roomStatus').innerHTML = statusBadge(room.status);

  renderRadar({ ...envCurrent.environment, ...envCurrent.noise }, avgReq(artworks));
  renderArtworkTable(artworks);
  renderHistory(history);
}

async function refreshHistoryByRange() {
  const roomId = roomIdFromPath();
  const range = document.getElementById('roomRange').value;
  const history = await apiGet(`/api/rooms/${encodeURIComponent(roomId)}/history?range=${range}`);
  renderHistory(history);
}

async function compareSelected() {
  const checked = Array.from(document.querySelectorAll('input[data-art-id]:checked')).map((el) => el.getAttribute('data-art-id'));
  const ids = checked.slice(0, 3);
  if (!ids.length) {
    document.getElementById('compareWrap').innerHTML = `<div class="small">Selecciona hasta 3 obras.</div>`;
    return;
  }

  const data = await apiGet(`/api/artworks/compare?ids=${ids.map(encodeURIComponent).join(',')}`);
  document.getElementById('compareWrap').innerHTML = data
    .map(
      (a) => `
      <article class="card">
        <img src="${a.image}" alt="${a.name}" style="width:100%;height:130px;object-fit:cover;border-radius:8px"/>
        <h4>${a.name}</h4>
        <div class="small">${a.artist || ''}</div>
        <div style="margin-top:8px">Riesgo: <strong>${formatNumber(a.degradationRisk, 3)}</strong></div>
        <div class="pill" style="margin-top:8px">Estado: ${a.conditionStatus || 'good'}</div>
      </article>
    `
    )
    .join('');
}

function wireActions() {
  const roomId = roomIdFromPath();

  document.getElementById('roomRange').addEventListener('change', refreshHistoryByRange);
  document.getElementById('compareBtn').addEventListener('click', compareSelected);

  document.getElementById('exportPdf').addEventListener('click', () => {
    window.open(`/api/rooms/${encodeURIComponent(roomId)}/passport?format=pdf`, '_blank');
  });
  document.getElementById('exportMd').addEventListener('click', () => {
    window.open(`/api/rooms/${encodeURIComponent(roomId)}/passport?format=md`, '_blank');
  });
}

document.addEventListener('DOMContentLoaded', () => {
  if (document.body.getAttribute('data-page') !== 'room-artwork') return;
  wireActions();
  loadRoomView().catch((err) => console.error(err));
  ensureSocket().on('update', () => loadRoomView());
});
"}

{"filePath":"/Users/mangelvilarino/Desktop/2-CUAT-4/GDEI/PRACTICAS/GDEI-P3/backend/static/js/control_center.js","content":"let alertsChart;

function setTab(tab) {
  document.querySelectorAll('[data-tab]').forEach((el) => {
    el.style.display = el.getAttribute('data-tab') === tab ? 'block' : 'none';
  });
  document.querySelectorAll('.tab-btn').forEach((btn) => {
    btn.classList.toggle('btn-primary', btn.getAttribute('data-target') === tab);
  });
}

async function loadAlertsTab() {
  const [alerts, stats] = await Promise.all([
    apiGet('/api/admin/alerts'),
    apiGet('/api/admin/alerts/stats'),
  ]);

  document.getElementById('alertsTableBody').innerHTML = alerts
    .map(
      (a) => `
      <tr>
        <td>${a.subCategory || '-'}</td>
        <td>${a.severity || '-'}</td>
        <td>${a.status || '-'}</td>
        <td>${a.alertSource || '-'}</td>
        <td>${a.dateIssued || '-'}</td>
        <td><button class="btn" data-resolve="${a.id}">${tr('resolve')}</button></td>
      </tr>
    `
    )
    .join('');

  document.querySelectorAll('button[data-resolve]').forEach((btn) => {
    btn.addEventListener('click', async () => {
      await apiSend(`/api/alerts/${encodeURIComponent(btn.getAttribute('data-resolve'))}/resolve`, 'PATCH');
      await loadAlertsTab();
    });
  });

  const labels = Object.keys(stats.byType || {});
  const values = Object.values(stats.byType || {});
  if (alertsChart) alertsChart.destroy();
  alertsChart = new Chart(document.getElementById('alertsStatsChart'), {
    type: 'bar',
    data: {
      labels,
      datasets: [{
        label: tr('alerts'),
        data: values,
        backgroundColor: '#d27d3f88',
        borderColor: '#d27d3f',
        borderWidth: 1,
      }],
    },
    options: { responsive: true, maintainAspectRatio: false },
  });
}

async function loadDevicesTab() {
  const devices = await apiGet('/api/admin/devices');
  const body = document.getElementById('devicesTableBody');
  body.innerHTML = devices
    .map(
      (d) => `
      <tr>
        <td>${d.name || d.id}</td>
        <td>${d.deviceState || '-'}</td>
        <td>${Math.round(Number(d.batteryLevel || 0) * 100)}%</td>
        <td>${formatNumber(d.latencyMs || 0, 1)} ms</td>
        <td>${formatNumber(d.prediction?.probability || 0, 3)}</td>
        <td>${d.maintenanceBadge ? '<span class="badge attention">Mantenimiento proximo</span>' : '<span class="badge optimal">OK</span>'}</td>
      </tr>
    `
    )
    .join('');
}

async function loadGrafanaTab() {
  const g = await apiGet('/api/grafana/admin');
  document.getElementById('adminGrafana').src = g.embed;
}

function wireTabs() {
  document.querySelectorAll('.tab-btn').forEach((btn) => {
    btn.addEventListener('click', async () => {
      const target = btn.getAttribute('data-target');
      setTab(target);
      if (target === 'alerts') await loadAlertsTab();
      if (target === 'devices') await loadDevicesTab();
      if (target === 'grafana') await loadGrafanaTab();
    });
  });
}

document.addEventListener('DOMContentLoaded', () => {
  if (document.body.getAttribute('data-page') !== 'control-center') return;
  wireTabs();
  setTab('alerts');
  loadAlertsTab().catch((err) => console.error(err));
  ensureSocket().on('alerts', () => loadAlertsTab());
  ensureSocket().on('devices', () => loadDevicesTab());
});
"}

{"filePath":"/Users/mangelvilarino/Desktop/2-CUAT-4/GDEI/PRACTICAS/GDEI-P3/backend/static/js/visitor.js","content":"function poiFromPath() {
  const parts = window.location.pathname.split('/').filter(Boolean);
  return decodeURIComponent(parts[1]);
}

function airBadge(status) {
  if (status === 'excellent') return '<span class="badge optimal">Aire excelente</span>';
  if (status === 'acceptable') return '<span class="badge attention">Aire aceptable</span>';
  return '<span class="badge critical">Aire mejorable</span>';
}

async function loadVisitorData() {
  const poi = poiFromPath();
  const [summary, recommended] = await Promise.all([
    apiGet(`/api/public/poi/${encodeURIComponent(poi)}/summary`),
    apiGet(`/api/public/poi/${encodeURIComponent(poi)}/recommended-room`),
  ]);

  document.getElementById('visitorTitle').textContent = summary.center.name;
  document.getElementById('airStatus').innerHTML = airBadge(summary.airStatus);
  document.getElementById('co2Val').textContent = `${formatNumber(summary.snapshot.avgCo2, 0)} ppm`;
  document.getElementById('tempVal').textContent = `${formatNumber(summary.snapshot.avgTemperature)} C`;
  document.getElementById('humVal').textContent = `${formatNumber(summary.snapshot.avgHumidity)} %`;
  document.getElementById('occVal').textContent = `${Math.round(summary.snapshot.avgOccupancy * 100)} %`;

  if (recommended && recommended.room) {
    document.getElementById('recommendedRoom').textContent =
      `Recomendacion: ${recommended.room.name} (indice ${formatNumber(recommended.comfortIndex, 1)})`;
  }
}

function appendChat(role, text) {
  const box = document.getElementById('chatBox');
  const el = document.createElement('div');
  el.className = `chat-msg ${role}`;
  el.textContent = text;
  box.appendChild(el);
  box.scrollTop = box.scrollHeight;
}

async function askChat() {
  const poi = poiFromPath();
  const input = document.getElementById('chatInput');
  const question = input.value.trim();
  if (!question) return;

  appendChat('user', question);
  input.value = '';

  try {
    const start = performance.now();
    const res = await apiSend('/api/public/chat/ask', 'POST', {
      poi_id: poi,
      question,
      language: AURA.lang,
    });
    const elapsed = Math.round(performance.now() - start);
    appendChat('bot', `${res.answer} (${elapsed} ms)`);
  } catch (err) {
    appendChat('bot', 'No ha sido posible responder ahora mismo.');
  }
}

function wireChat() {
  document.getElementById('chatSend').addEventListener('click', askChat);
  document.getElementById('chatInput').addEventListener('keydown', (e) => {
    if (e.key === 'Enter') askChat();
  });
}

document.addEventListener('DOMContentLoaded', () => {
  if (document.body.getAttribute('data-page') !== 'visitor') return;
  wireChat();
  loadVisitorData().catch((err) => console.error(err));
  setInterval(() => loadVisitorData().catch((err) => console.error(err)), 60000);
});
"}

