import re,glob,os
base='backend'
js_files=sorted(glob.glob(base+'/static/js/*.js'))
templates=sorted(glob.glob(base+'/templates/*.html'))+sorted(glob.glob(base+'/templates/*.jinja'))+sorted(glob.glob(base+'/templates/*.j2'))
# map js -> templates that include it
includes={j:[] for j in js_files}
for t in templates:
    c=open(t,encoding='utf-8').read()
    for j in js_files:
        name=os.path.basename(j)
        if f"filename='js/{name}'" in c or f'filename="js/{name}"' in c or f'/js/{name}' in c:
            includes[j].append(t)

id_re=re.compile(r"getElementById\s*\(\s*['\"]([^'\"]+)['\"]\s*\)")
for j in js_files:
    c=open(j,encoding='utf-8').read()
    ids=sorted(set(id_re.findall(c)))
    tpls=includes[j]
    if not tpls:
        continue
    for idv in ids:
        found=False
        for t in tpls:
            tc=open(t,encoding='utf-8').read()
            if re.search(rf"id\s*=\s*['\"]{re.escape(idv)}['\"]",tc):
                found=True; break
        if not found:
            print(f"{os.path.relpath(j)} -> {idv} (templates: {', '.join(os.path.relpath(t) for t in tpls)})")
PY

