import re,glob,os
js=sorted(glob.glob('backend/static/js/*.js'))
tpls=sorted(glob.glob('backend/templates/*.html'))
inc={j:[] for j in js}
for t in tpls:
  c=open(t,encoding='utf-8').read()
  for j in js:
    n=os.path.basename(j)
    if f"js/{n}" in c:
      inc[j].append(t)
id_re=re.compile(r"getElementById\s*\(\s*['\"]([^'\"]+)['\"]\s*\)")
miss=[]
for j in js:
  if not inc[j]:
    continue
  jc=open(j,encoding='utf-8').read()
  for i in sorted(set(id_re.findall(jc))):
    ok=False
    for t in inc[j]:
      tc=open(t,encoding='utf-8').read()
      if re.search(rf"id\s*=\s*['\"]{re.escape(i)}['\"]",tc):
        ok=True; break
    if not ok:
      miss.append((j,i,inc[j]))
for j,i,tt in miss:
  print(f"{j} -> {i} ({', '.join(tt)})")
print('MISMATCH_COUNT',len(miss))
PY

