diff --git a/backend/static/css/style.css b/backend/static/css/style.css
new file mode 100644
--- /dev/null
+++ b/backend/static/css/style.css
@@ -0,0 +1,420 @@
+@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;700&family=Literata:opsz,wght@7..72,500;7..72,700&display=swap');
+
+:root {
+  --font-ui: 'Space Grotesk', sans-serif;
+  --font-display: 'Literata', serif;
+
+  --bg: #f2efe8;
+  --panel: #fff9ef;
+  --text: #1d2627;
+  --muted: #516266;
+  --accent: #0e7c74;
+  --accent-2: #d27d3f;
+  --danger: #b5443c;
+  --warn: #a86b18;
+  --ok: #26875f;
+
+  --border: #d7cfbe;
+  --shadow: 0 10px 30px rgba(29, 38, 39, 0.12);
+  --radius: 14px;
+}
+
+[data-theme="dark"] {
+  --bg: #101919;
+  --panel: #172323;
+  --text: #e9f0ec;
+  --muted: #99ada7;
+  --accent: #45c5bb;
+  --accent-2: #f0a15d;
+  --danger: #ea7164;
+  --warn: #f0bb62;
+  --ok: #51d494;
+
+  --border: #28403e;
+  --shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
+}
+
+* {
+  box-sizing: border-box;
+}
+
+body {
+  margin: 0;
+  font-family: var(--font-ui);
+  color: var(--text);
+  background:
+    radial-gradient(circle at 8% 12%, rgba(14, 124, 116, 0.18) 0, transparent 30%),
+    radial-gradient(circle at 92% 6%, rgba(210, 125, 63, 0.16) 0, transparent 35%),
+    linear-gradient(180deg, var(--bg), color-mix(in srgb, var(--bg) 88%, #000 12%));
+  min-height: 100vh;
+}
+
+a {
+  color: inherit;
+  text-decoration: none;
+}
+
+.app-shell {
+  width: min(1320px, 94vw);
+  margin: 18px auto 28px;
+}
+
+.topbar {
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+  gap: 12px;
+  padding: 14px 18px;
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  background: color-mix(in srgb, var(--panel) 94%, transparent);
+  backdrop-filter: blur(8px);
+  box-shadow: var(--shadow);
+  position: sticky;
+  top: 10px;
+  z-index: 20;
+}
+
+.brand {
+  display: flex;
+  align-items: center;
+  gap: 12px;
+}
+
+.brand-mark {
+  width: 36px;
+  height: 36px;
+  border-radius: 10px;
+  background: linear-gradient(145deg, var(--accent), var(--accent-2));
+  box-shadow: 0 4px 18px color-mix(in srgb, var(--accent) 55%, transparent);
+}
+
+.brand h1 {
+  margin: 0;
+  font-family: var(--font-display);
+  font-size: 1.2rem;
+  letter-spacing: 0.02em;
+}
+
+.toolbar {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 8px;
+}
+
+.btn,
+select,
+input,
+textarea {
+  font: inherit;
+}
+
+.btn {
+  border: 1px solid var(--border);
+  background: var(--panel);
+  color: var(--text);
+  padding: 8px 12px;
+  border-radius: 10px;
+  cursor: pointer;
+  transition: transform 0.2s ease, background 0.2s ease;
+}
+
+.btn:hover {
+  transform: translateY(-1px);
+}
+
+.btn-primary {
+  background: linear-gradient(145deg, var(--accent), color-mix(in srgb, var(--accent) 70%, #fff 30%));
+  color: #fff;
+  border: none;
+}
+
+.nav-links {
+  display: flex;
+  gap: 8px;
+  flex-wrap: wrap;
+}
+
+.nav-link {
+  padding: 6px 10px;
+  border-radius: 8px;
+  border: 1px solid transparent;
+  color: var(--muted);
+}
+
+.nav-link.active,
+.nav-link:hover {
+  border-color: var(--border);
+  color: var(--text);
+  background: color-mix(in srgb, var(--accent) 8%, var(--panel));
+}
+
+.grid {
+  display: grid;
+  gap: 14px;
+}
+
+.grid-2 {
+  grid-template-columns: repeat(2, minmax(0, 1fr));
+}
+
+.grid-3 {
+  grid-template-columns: repeat(3, minmax(0, 1fr));
+}
+
+.grid-4 {
+  grid-template-columns: repeat(4, minmax(0, 1fr));
+}
+
+.card {
+  background: var(--panel);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  padding: 14px;
+  box-shadow: var(--shadow);
+}
+
+.card h2,
+.card h3,
+.card h4 {
+  font-family: var(--font-display);
+  margin-top: 0;
+}
+
+.kpi {
+  display: flex;
+  flex-direction: column;
+  gap: 4px;
+}
+
+.kpi .value {
+  font-size: 1.55rem;
+  font-weight: 700;
+}
+
+.badge {
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+  font-size: 0.82rem;
+  border-radius: 999px;
+  padding: 3px 10px;
+  border: 1px solid transparent;
+}
+
+.badge.optimal {
+  color: var(--ok);
+  background: color-mix(in srgb, var(--ok) 13%, transparent);
+}
+
+.badge.attention {
+  color: var(--warn);
+  background: color-mix(in srgb, var(--warn) 13%, transparent);
+}
+
+.badge.critical {
+  color: var(--danger);
+  background: color-mix(in srgb, var(--danger) 13%, transparent);
+}
+
+.table-wrap {
+  overflow: auto;
+}
+
+table {
+  width: 100%;
+  border-collapse: collapse;
+}
+
+th,
+td {
+  border-bottom: 1px solid var(--border);
+  padding: 8px;
+  text-align: left;
+  font-size: 0.92rem;
+}
+
+th {
+  color: var(--muted);
+  font-weight: 500;
+}
+
+.leaflet-map,
+.chart-wrap,
+.three-wrap,
+.grafana-frame {
+  border: 1px solid var(--border);
+  border-radius: 12px;
+  overflow: hidden;
+  background: color-mix(in srgb, var(--panel) 96%, #000 4%);
+}
+
+.leaflet-map {
+  height: 420px;
+}
+
+.chart-wrap {
+  min-height: 260px;
+  padding: 10px;
+}
+
+.three-wrap {
+  height: 520px;
+}
+
+.grafana-frame {
+  height: 460px;
+}
+
+iframe {
+  width: 100%;
+  height: 100%;
+  border: none;
+}
+
+.alert-list {
+  max-height: 360px;
+  overflow: auto;
+  display: grid;
+  gap: 8px;
+}
+
+.alert-item {
+  border: 1px solid var(--border);
+  border-left: 5px solid var(--warn);
+  border-radius: 10px;
+  padding: 8px;
+  background: color-mix(in srgb, var(--panel) 92%, #fff 8%);
+}
+
+.alert-item.critical {
+  border-left-color: var(--danger);
+}
+
+.alert-item.optimal {
+  border-left-color: var(--ok);
+}
+
+.fade-up {
+  animation: fadeUp 0.45s ease both;
+}
+
+.stagger > * {
+  opacity: 0;
+  transform: translateY(10px);
+  animation: fadeUp 0.4s ease forwards;
+}
+
+.stagger > *:nth-child(1) { animation-delay: 0.02s; }
+.stagger > *:nth-child(2) { animation-delay: 0.06s; }
+.stagger > *:nth-child(3) { animation-delay: 0.1s; }
+.stagger > *:nth-child(4) { animation-delay: 0.14s; }
+.stagger > *:nth-child(5) { animation-delay: 0.18s; }
+.stagger > *:nth-child(6) { animation-delay: 0.22s; }
+
+@keyframes fadeUp {
+  from {
+    opacity: 0;
+    transform: translateY(12px);
+  }
+  to {
+    opacity: 1;
+    transform: translateY(0);
+  }
+}
+
+.controls-row {
+  display: flex;
+  gap: 10px;
+  flex-wrap: wrap;
+  align-items: center;
+}
+
+.input,
+select,
+textarea {
+  border: 1px solid var(--border);
+  border-radius: 9px;
+  background: var(--panel);
+  color: var(--text);
+  padding: 8px 10px;
+}
+
+.split {
+  display: grid;
+  grid-template-columns: 1.4fr 1fr;
+  gap: 14px;
+}
+
+.pill {
+  border: 1px solid var(--border);
+  border-radius: 999px;
+  padding: 4px 10px;
+  color: var(--muted);
+  font-size: 0.84rem;
+}
+
+.small {
+  font-size: 0.83rem;
+  color: var(--muted);
+}
+
+.visitor-shell {
+  width: min(760px, 94vw);
+  margin: 18px auto;
+}
+
+.chat-box {
+  display: grid;
+  gap: 8px;
+  max-height: 260px;
+  overflow: auto;
+  padding: 8px;
+  border: 1px solid var(--border);
+  border-radius: 12px;
+}
+
+.chat-msg {
+  border-radius: 10px;
+  padding: 8px 10px;
+  background: color-mix(in srgb, var(--accent) 10%, var(--panel));
+}
+
+.chat-msg.bot {
+  background: color-mix(in srgb, var(--accent-2) 16%, var(--panel));
+}
+
+@media (max-width: 1024px) {
+  .grid-4 {
+    grid-template-columns: repeat(2, minmax(0, 1fr));
+  }
+
+  .split {
+    grid-template-columns: 1fr;
+  }
+}
+
+@media (max-width: 720px) {
+  .app-shell {
+    width: 96vw;
+  }
+
+  .topbar {
+    position: static;
+    padding: 12px;
+  }
+
+  .grid-3,
+  .grid-2,
+  .grid-4 {
+    grid-template-columns: 1fr;
+  }
+
+  .leaflet-map {
+    height: 320px;
+  }
+
+  .three-wrap {
+    height: 380px;
+  }
+}
```

